-- Run only in the isolated fixture created by board_minutes_tasks_run.sh.
BEGIN;
DO $$ DECLARE v uuid; mid uuid; v2 uuid; aid uuid; tid uuid; n integer; result jsonb; BEGIN
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 SET LOCAL ROLE authenticated;
 v:=public.board_minutes_save_revision(NULL,NULL,'upload','synthetic-new','2026-11-10','Synthetic minutes','Report','[]','["Check permit","Check schedule","Check register"]',NULL,true,NULL);
 SELECT meeting_id INTO mid FROM public.board_minutes_versions WHERE id=v;
 RESET ROLE;
 INSERT INTO public.board_minutes_import_details(version_id,details,source_text,created_by) VALUES(v,'{"status":"concept","action_rows":[{"action":"Check permit","owner":"Tester + Other","deadline":"2026-12-01"},{"action":"Check schedule","owner":"Bestuur","deadline":"Later"},{"action":"Check register","owner":"Tester + betrokken bestuursleden","deadline":""}]}','Source',auth.uid());
 SET LOCAL ROLE authenticated;
 n:=public.board_minutes_sync_tasks(v,false); IF n<>3 THEN RAISE EXCEPTION 'Expected 3 actions, got %',n; END IF;
 SELECT action_id INTO aid FROM public.board_minutes_action_versions WHERE version_id=v AND row_index=0;
 SELECT task_id INTO tid FROM public.board_minutes_action_links WHERE id=aid;
 IF (SELECT count(*) FROM public.board_minutes_action_assignees WHERE action_id=aid)<>2 THEN RAISE EXCEPTION 'Multiple explicit names not matched'; END IF;
 IF (SELECT deadline FROM public.internal_tasks WHERE id=tid)<>'2026-12-01' THEN RAISE EXCEPTION 'Explicit date lost'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.board_minutes_action_links l JOIN public.board_minutes_action_versions a ON a.action_id=l.id WHERE a.version_id=v AND a.row_index=1 AND l.needs_assignment) THEN RAISE EXCEPTION 'Collective guessed'; END IF;
 IF (SELECT count(*) FROM public.board_minutes_action_assignees s JOIN public.board_minutes_action_versions a ON a.action_id=s.action_id WHERE a.version_id=v AND a.row_index=2)<>1 THEN RAISE EXCEPTION 'Explicit person plus collective lost'; END IF;
 PERFORM public.board_minutes_sync_tasks(v,false);
 IF (SELECT count(*) FROM public.internal_tasks)<>3 THEN RAISE EXCEPTION 'Duplicate sync'; END IF;
 UPDATE public.internal_tasks SET status='afgerond' WHERE id=tid;
 IF NOT EXISTS(SELECT 1 FROM public.internal_tasks WHERE id=tid AND completed_by=auth.uid() AND completed_at IS NOT NULL) THEN RAISE EXCEPTION 'Actual completion actor/time missing'; END IF;
 result:=public.board_minutes_tasks(v);
 IF result->'rows'->0->>'status'<>'afgerond' THEN RAISE EXCEPTION 'Crossview completion missing'; END IF;
 v2:=public.board_minutes_save_action_revision(jsonb_build_object('meetingId',mid,'expectedVersion',v,'source','upload','sourceId','synthetic-new','date','2026-11-10','title','Renamed minutes','report','Report','decisions','[]'::jsonb,'actions','["Renamed action"]'::jsonb,'sourceUrl','','confirm',true,'action_rows',jsonb_build_array(jsonb_build_object('action_id',aid,'action','Renamed action','owner','Tester + Other','deadline','Later'))));
 PERFORM public.board_minutes_sync_tasks(v2,false);
 IF (SELECT count(*) FROM public.internal_tasks)<>3 THEN RAISE EXCEPTION 'Rename duplicated tasks'; END IF;
 IF (public.board_minutes_tasks(v2)->'rows'->0->>'status')<>'afgerond' THEN RAISE EXCEPTION 'Completion reset'; END IF;
 UPDATE public.internal_tasks SET status='te_doen' WHERE id=tid;
 IF EXISTS(SELECT 1 FROM public.internal_tasks WHERE id=tid AND (completed_by IS NOT NULL OR completed_at IS NOT NULL)) THEN RAISE EXCEPTION 'Reopen audit not cleared'; END IF;
 IF public.board_minutes_tasks(v)->'rows'->0->>'status'<>'te_doen' OR public.board_minutes_tasks(v2)->'rows'->0->>'status'<>'te_doen' THEN RAISE EXCEPTION 'Reopen crossview missing'; END IF;
 PERFORM public.board_minutes_task_assignment(aid,ARRAY['00000000-0000-0000-0000-000000000006'::uuid],true);
 IF (SELECT assignee_id FROM public.internal_tasks WHERE id=tid)<>'00000000-0000-0000-0000-000000000006' THEN RAISE EXCEPTION 'Admin choice missing'; END IF;
 BEGIN UPDATE public.internal_tasks SET project_id=gen_random_uuid() WHERE id=tid; RAISE EXCEPTION 'Project leak allowed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Project leak allowed' THEN RAISE; END IF; END;
 BEGIN UPDATE public.internal_tasks SET board_minutes_private=false WHERE id=tid; RAISE EXCEPTION 'Privacy removed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM='Privacy removed' THEN RAISE; END IF; END;
 RESET ROLE;
 IF (SELECT count(*) FROM public.task_notifications)<>0 OR (SELECT count(*) FROM public.outlook_deadline_outbox)<>0 THEN RAISE EXCEPTION 'Notification/Outlook side effect'; END IF;
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true); SET LOCAL ROLE authenticated;
 IF jsonb_array_length(public.board_minutes_tasks(v)->'rows')<>3 THEN RAISE EXCEPTION 'Board read denied'; END IF;
 IF (SELECT count(*) FROM public.internal_tasks)<>0 THEN RAISE EXCEPTION 'Board general task access widened'; END IF;
 BEGIN PERFORM public.board_minutes_sync_tasks(v2,false); RAISE EXCEPTION 'Board write allowed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',true); SET LOCAL ROLE authenticated;
 IF (SELECT count(*) FROM public.internal_tasks)<>0 OR (SELECT count(*) FROM public.board_minutes_action_versions)<>0 THEN RAISE EXCEPTION 'Member task leak'; END IF;
 BEGIN PERFORM public.board_minutes_tasks(v); RAISE EXCEPTION 'Member RPC leak'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.board_minutes_task_assignment(aid,'{}',true); RAISE EXCEPTION 'Member mutation'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','',true); SET LOCAL ROLE anon;
 BEGIN PERFORM public.board_minutes_tasks(v); RAISE EXCEPTION 'Anonymous RPC leak'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
 SET LOCAL ROLE authenticated;
 v2:=public.board_minutes_save_revision(NULL,NULL,'topical','synthetic-history','2026-06-04','Old agenda','','[]','["Do not activate"]',NULL,true,NULL);
 IF public.board_minutes_sync_tasks(v2,true)<>0 THEN RAISE EXCEPTION 'Historical import activated'; END IF;
 IF (SELECT count(*) FROM public.internal_tasks)<>3 THEN RAISE EXCEPTION 'Historical task created'; END IF;
 v2:=public.board_minutes_save_action_revision(jsonb_build_object('meetingId',NULL,'expectedVersion',NULL,'source','upload','sourceId','synthetic-future','date','2026-11-11','title','New minutes','report','Report','decisions','[]'::jsonb,'actions','["Automatic new task"]'::jsonb,'sourceUrl','','confirm',true,'action_rows',jsonb_build_array(jsonb_build_object('action','Automatic new task','owner','Tester','deadline',''))));
 SET CONSTRAINTS ALL IMMEDIATE;
 IF (SELECT count(*) FROM public.internal_tasks)<>4 OR jsonb_array_length(public.board_minutes_tasks(v2)->'rows')<>1 THEN RAISE EXCEPTION 'New save did not auto-sync'; END IF;
 RESET ROLE;
 IF EXISTS(SELECT 1 FROM public.task_notifications) OR EXISTS(SELECT 1 FROM public.outlook_deadline_outbox) THEN RAISE EXCEPTION 'Automatic save notified somebody'; END IF;
 RAISE NOTICE 'PASS: multiple explicit names, collective review, date, idempotency, rename, completion/reopen crossview, admin choice, member denial, no external effects';
END $$;
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK;